-- V3.3.6 Planificacion por cobertura
create table if not exists public.post_plans(id uuid primary key default gen_random_uuid(),guard_post_id uuid not null references public.guard_posts(id),start_date date not null,end_date date not null,active boolean not null default true,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),check(end_date>=start_date));
create table if not exists public.post_plan_slots(id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.post_plans(id) on delete cascade,slot_order int not null,start_time time not null,duration_hours int not null check(duration_hours in(8,12)),primary_personnel_id uuid references public.personnel(id),relief_personnel_id uuid references public.personnel(id),work_days int not null default 5,rest_days int not null default 2,unique(plan_id,slot_order),check(primary_personnel_id is null or relief_personnel_id is null or primary_personnel_id<>relief_personnel_id));
alter table public.shifts add column if not exists plan_slot_id uuid references public.post_plan_slots(id) on delete set null;
alter table public.post_plans enable row level security;alter table public.post_plan_slots enable row level security;
drop policy if exists post_plans_staff_read on public.post_plans;create policy post_plans_staff_read on public.post_plans for select to authenticated using(public.current_user_role() in('ADMIN','RRHH','OPERACIONES','SUPERVISOR'));
drop policy if exists post_plan_slots_staff_read on public.post_plan_slots;create policy post_plan_slots_staff_read on public.post_plan_slots for select to authenticated using(public.current_user_role() in('ADMIN','RRHH','OPERACIONES','SUPERVISOR'));
create or replace function public.provica_create_post_plan(p_post uuid,p_start date,p_months int,p_shift_hours int,p_start_time time)returns uuid language plpgsql security definer set search_path=public as $$declare pid uuid;cov int;slots int;i int;st time;begin if current_user_role() not in('ADMIN','OPERACIONES')then raise exception 'No autorizado';end if;if p_months<1 or p_months>12 or p_shift_hours not in(8,12)then raise exception 'Parametros invalidos';end if;select coverage_hours into cov from guard_posts where id=p_post and active=true;if cov is null then raise exception 'Puesto inexistente';end if;if cov%p_shift_hours<>0 then raise exception 'Cobertura %h incompatible con jornada %h',cov,p_shift_hours;end if;slots:=cov/p_shift_hours;insert into post_plans(guard_post_id,start_date,end_date,created_by)values(p_post,p_start,(p_start+make_interval(months=>p_months))::date-1,auth.uid())returning id into pid;for i in 0..slots-1 loop st:=(p_start_time+(i*p_shift_hours)*interval '1 hour')::time;insert into post_plan_slots(plan_id,slot_order,start_time,duration_hours)values(pid,i+1,st,p_shift_hours);end loop;return pid;end$$;
create or replace function public.provica_assign_plan_slot(p_slot uuid,p_primary uuid,p_relief uuid)returns void language plpgsql security definer set search_path=public as $$begin if current_user_role() not in('ADMIN','OPERACIONES')then raise exception 'No autorizado';end if;if p_primary is not null and not exists(select 1 from personnel where id=p_primary and active and personnel_type='OPERATIVO' and intended_role='GUARDIA')then raise exception 'Titular invalido';end if;if p_relief is not null and not exists(select 1 from personnel where id=p_relief and active and personnel_type='OPERATIVO' and intended_role='GUARDIA')then raise exception 'Relevo invalido';end if;update post_plan_slots set primary_personnel_id=p_primary,relief_personnel_id=p_relief where id=p_slot;end$$;
create or replace function public.provica_generate_post_plan(p_plan uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare pl post_plans%rowtype;sl post_plan_slots%rowtype;d date;a timestamptz;b timestamptz;who uuid;prof uuid;n int:=0;idx int;begin if current_user_role() not in('ADMIN','OPERACIONES')then raise exception 'No autorizado';end if;select * into pl from post_plans where id=p_plan and active for update;if not found then raise exception 'Plan inexistente';end if;if exists(select 1 from post_plan_slots where plan_id=p_plan and(primary_personnel_id is null or relief_personnel_id is null))then raise exception 'Complete titular y relevo de todos los cajones';end if;delete from shifts where plan_slot_id in(select id from post_plan_slots where plan_id=p_plan)and status='PROGRAMADO' and starts_at>now();for sl in select * from post_plan_slots where plan_id=p_plan order by slot_order loop d:=pl.start_date;idx:=0;while d<=pl.end_date loop who:=case when(idx%(sl.work_days+sl.rest_days))<sl.work_days then sl.primary_personnel_id else sl.relief_personnel_id end;a:=(d::text||' '||sl.start_time::text)::timestamp at time zone 'America/Guayaquil';b:=a+make_interval(hours=>sl.duration_hours);if a>now()then if exists(select 1 from shifts where personnel_id=who and status<>'CANCELADO' and starts_at<b and ends_at>a)then raise exception 'Conflicto para % el %',(select person_code from personnel where id=who),d;end if;select profile_id into prof from personnel where id=who;insert into shifts(guard_post_id,guard_id,personnel_id,starts_at,ends_at,status,plan_slot_id)values(pl.guard_post_id,prof,who,a,b,'PROGRAMADO',sl.id);n:=n+1;end if;d:=d+1;idx:=idx+1;end loop;end loop;return jsonb_build_object('shifts_created',n);end$$;
revoke all on function public.provica_create_post_plan(uuid,date,int,int,time) from public;revoke all on function public.provica_assign_plan_slot(uuid,uuid,uuid) from public;revoke all on function public.provica_generate_post_plan(uuid) from public;grant execute on function public.provica_create_post_plan(uuid,date,int,int,time) to authenticated;grant execute on function public.provica_assign_plan_slot(uuid,uuid,uuid) to authenticated;grant execute on function public.provica_generate_post_plan(uuid) to authenticated;